// 区块加载/卸载开关
let chunkLoadEnabled = true;
let chunkUnloadEnabled = true;

// 批次处理参数
let chunksPerBatch = 10; // 每批次处理的区块数量，可动态调整 (1-10)
const BATCH_INTERVAL_MS = 100;
let batchTimer = null;

// 修改的方块记录（key: "x,y,z", value: blockType）
const modifiedBlocks = new Map();
// 修改的方块按区块分组
const modifiedBlocksByChunk = new Map();

// Phase 5: 统一的方块朝向数据（key: "x,y,z", value: RenderOrientation）
// 合并了原来的 furnaceFacings 和 woodFacings
const blockOrientations = new Map();

// ===== 门数据存储 =====
// 门朝向数据 key: "x,y,z", value: orientation ('north'|'south'|'east'|'west')
const doorOrientations = new Map();
// 门开关状态 key: "x,y,z", value: isOpen (true=开, false=关)
