// ===== 区块处理共享常量 =====
const FACE_COUNT = 6;
const DIRECTION_OFFSETS = [
  [0, 0.5, 0],   // TOP: Y轴正方向偏移
  [0, -0.5, 0],  // BOTTOM: Y轴负方向偏移
  [0.5, 0, 0],   // RIGHT: X轴正方向偏移
  [-0.5, 0, 0],  // LEFT: X轴负方向偏移
  [0, 0, 0.5],   // FRONT: Z轴正方向偏移
  [0, 0, -0.5],  // BACK: Z轴负方向偏移
];
const SCALE_CONFIGS = [
  { widthAxis: 0, heightAxis: 2 },  // TOP: width=X, height=Z
  { widthAxis: 0, heightAxis: 2 },  // BOTTOM: width=X, height=Z
  { widthAxis: 1, heightAxis: 2 },  // RIGHT: width=Y, height=Z
  { widthAxis: 1, heightAxis: 2 },  // LEFT: width=Y, height=Z
  { widthAxis: 0, heightAxis: 1 },  // FRONT: width=X, height=Y
  { widthAxis: 0, heightAxis: 1 },  // BACK: width=X, height=Y
];

// ===== Phase 4: 通用朝向矩阵 =====
// 所有有朝向方块共享的面映射规则
// FaceDirection: TOP=0, BOTTOM=1, RIGHT=2, LEFT=3, FRONT=4, BACK=5
// 朝向表示"方块的正面朝向世界坐标系的哪个方向"
const ORIENTATION_FACE_MAP = {
  // 正面朝上（+Y）：几何 TOP 面显示正面纹理，BOTTOM 面显示背面纹理
  'up': { 0: 'front', 1: 'back', 2: 'right', 3: 'left', 4: 'top', 5: 'bottom' },
  // 正面朝下（-Y）：几何 TOP 面显示背面纹理，BOTTOM 面显示正面纹理
  'down': { 0: 'back', 1: 'front', 2: 'right', 3: 'left', 4: 'bottom', 5: 'top' },
  // 正面朝北（-Z）：几何 FRONT 面显示背面纹理
  'north': { 0: 'top', 1: 'bottom', 2: 'right', 3: 'left', 4: 'back', 5: 'front' },
  // 正面朝南（+Z）：几何 FRONT 面显示正面纹理
  'south': { 0: 'top', 1: 'bottom', 2: 'right', 3: 'left', 4: 'front', 5: 'back' },
  // 正面朝东（+X）：几何 RIGHT 面显示正面纹理
  'east': { 0: 'top', 1: 'bottom', 2: 'front', 3: 'back', 4: 'right', 5: 'left' },
  // 正面朝西（-X）：几何 LEFT 面显示正面纹理
  'west': { 0: 'top', 1: 'bottom', 2: 'back', 3: 'front', 4: 'left', 5: 'right' }
};

// 槽位名称到 FaceDirection 的映射
