// ===== Greedy Meshing 算法 =====
function getFaceKey(pos, direction) {
  return pos.x + ',' + pos.y + ',' + pos.z;
}

function getFixedCoord(pos, direction) {
  if (direction === 0 || direction === 1) return pos.y;
  else if (direction === 2 || direction === 3) return pos.x;
  else return pos.z;
}

function getNextPosAlongPrimary(startPos, offset, direction) {
  if (direction === 0 || direction === 1) return { x: startPos.x + offset, y: startPos.y, z: startPos.z };
  else if (direction === 2 || direction === 3) return { x: startPos.x, y: startPos.y + offset, z: startPos.z };
  else return { x: startPos.x + offset, y: startPos.y, z: startPos.z };
}

function getPosInRect(startPos, primaryOffset, secondaryOffset, direction) {
  if (direction === 0 || direction === 1) return { x: startPos.x + primaryOffset, y: startPos.y, z: startPos.z + secondaryOffset };
  else if (direction === 2 || direction === 3) return { x: startPos.x, y: startPos.y + primaryOffset, z: startPos.z + secondaryOffset };
  else return { x: startPos.x + primaryOffset, y: startPos.y + secondaryOffset, z: startPos.z };
}

function markProcessed(startPos, width, height, direction, faceMap, processed) {
  for (let h = 0; h < height; h++) {
    for (let w = 0; w < width; w++) {
      const pos = getPosInRect(startPos, w, h, direction);
      const key = getFaceKey(pos, direction);
      processed.add(key);
    }
  }
}

function extendAlongPrimaryAxis(startPos, direction, faceMap, processed) {
  let width = 1;
  const fixedCoord = getFixedCoord(startPos, direction);
  while (true) {
    const nextPos = getNextPosAlongPrimary(startPos, width, direction);
    const key = getFaceKey(nextPos, direction);
    if (processed.has(key) || !faceMap.has(key)) break;
    const nextFixed = getFixedCoord(nextPos, direction);
    if (nextFixed !== fixedCoord) break;
    width++;
  }
  return width;
}

function extendAlongSecondaryAxis(startPos, width, direction, faceMap, processed) {
  let height = 1;
  const fixedCoord = getFixedCoord(startPos, direction);
  while (true) {
    let allExist = true;
    for (let w = 0; w < width; w++) {
      const checkPos = getPosInRect(startPos, w, height, direction);
      const key = getFaceKey(checkPos, direction);
      if (processed.has(key) || !faceMap.has(key)) { allExist = false; break; }
      const checkFixed = getFixedCoord(checkPos, direction);
      if (checkFixed !== fixedCoord) { allExist = false; break; }
    }
    if (!allExist) break;
    height++;
  }
  return height;
}

function findLargestRect(startPos, direction, faceMap, processed) {
  let width = 1, height = 1;
  const fixedCoord = getFixedCoord(startPos, direction);
  width = extendAlongPrimaryAxis(startPos, direction, faceMap, processed);
  height = extendAlongSecondaryAxis(startPos, width, direction, faceMap, processed);
  markProcessed(startPos, width, height, direction, faceMap, processed);
  return { x: startPos.x, y: startPos.y, z: startPos.z, width, height };
}

function greedyMergeFaces(positions, direction) {
  const faceMap = new Map();
  for (const pos of positions) {
    const key = getFaceKey(pos, direction);
    faceMap.set(key, pos);
  }
  const processed = new Set();
  const mergedFaces = [];
  for (const pos of positions) {
    const key = getFaceKey(pos, direction);
    if (processed.has(key)) continue;
    const merged = findLargestRect(pos, direction, faceMap, processed);
    mergedFaces.push(merged);
  }
  return mergedFaces;
}

function applyGreedyMeshing(facesByBlockType) {
  const result = [];
  if (!facesByBlockType || !Array.isArray(facesByBlockType)) return result;

  for (const blockData of facesByBlockType) {
    if (!blockData || blockData.blockType === undefined) continue;
    if (!blockData.directions || !Array.isArray(blockData.directions)) continue;

    const blockType = blockData.blockType;
    const mergedDirections = [];

    for (const dirData of blockData.directions) {
      if (!dirData || dirData.direction === undefined) continue;
      const direction = dirData.direction;
      const textureGroups = dirData.textureGroups;

      // Phase 7: 使用新的 textureGroups 数据结构
      if (!textureGroups || textureGroups.size === 0) {
        mergedDirections.push({ direction, mergedFaces: [] });
        continue;
      }

      // 对每个纹理索引组分别执行 Greedy Meshing
      const allMergedFaces = [];
      for (const [textureIndex, group] of textureGroups) {
        const mergedFaces = greedyMergeFaces(group.positions, direction);
        // 为合并后的面片添加纹理索引
        for (const face of mergedFaces) {
          face.textureIndex = textureIndex;
        }
        allMergedFaces.push(...mergedFaces);
      }

      mergedDirections.push({ direction, mergedFaces: allMergedFaces });
    }
    result.push({ blockType, directions: mergedDirections });
  }
  return result;
}

