// ===== 数据驱动的方块属性判断 =====
// 使用从 blockRegistry 序列化的 BLOCK_PROPERTIES 数据
// 替代硬编码的透明/液体/碰撞集合

// 判断方块是否透明（不遮挡相邻方块的面）
function isTransparent(block) {
  return isBlockTransparentForWorker(block);
}

// 判断方块是否有碰撞体积
function hasCollision(block) {
  return hasBlockCollisionForWorker(block);
}

// 判断是否应该渲染当前方块的面（考虑水方块和树叶的特殊剔除规则）
// 规则：
// 1. 其他方块类型暴露在水的面不剔除（可见）
// 2. 水暴露在水的面要剔除（内部面隐藏）
// 3. 水暴露在不透明方块的面要剔除（被遮挡）
// 4. 水暴露在空气/透明非水方块的面要渲染（暴露面，包括侧面和底面）
// 5. 树叶不进行内部剔除（相邻树叶之间渲染面）
// 6. 透明方块（如玻璃）：只有相同的透明方块才进行内部剔除
// 7. 透明方块对空气：渲染面（不剔除）
function shouldRenderFace(currentBlock, neighborBlock, direction) {
  const isCurrentWater = isBlockLiquidForWorker(currentBlock);
  const isNeighborWater = isBlockLiquidForWorker(neighborBlock);
  const isCurrentLeaves = isBlockLeavesForWorker(currentBlock);
  const isNeighborLeaves = isBlockLeavesForWorker(neighborBlock);
  const isNeighborTransparent = isBlockTransparentForWorker(neighborBlock);
  const isNeighborAir = neighborBlock === 0; // 空气方块 blockType 为 0
  
  if (isCurrentWater) {
    // 水方块渲染规则：
    // 1. 水对水：不渲染（内部面剔除）
    // 2. 水对不透明方块：不渲染（被遮挡）
    // 3. 水对空气/透明非水方块：渲染（暴露面）
    // 这样水体会有侧面和底面，看起来有厚度
    if (isNeighborWater) return false; // 水对水不渲染
    if (!isNeighborTransparent) return false; // 水对不透明方块不渲染
    return true; // 水对空气/透明非水方块渲染
  } else if (isCurrentLeaves) {
    // 树叶：不进行内部剔除
    // 树叶对树叶：渲染面（不剔除）
    // 树叶对透明方块：渲染面
    // 树叶对不透明方块：不渲染（被遮挡）
    if (isNeighborLeaves) {
      // 树叶对树叶：渲染面（不进行内部剔除）
      return true;
    }
    // 火把和门是 InstancedMesh 渲染，不参与面片剔除
    // 如果相邻是火把或门，则渲染面
    if (isTorchBlock(neighborBlock) || isDoorBlock(neighborBlock)) {
      return true;
    }
    // 树叶对其他方块：如果相邻是透明方块（包括水），则渲染面
    return isNeighborTransparent;
  } else {
    // 其他透明方块（如玻璃）：只有相同的透明方块才进行内部剔除
    const isCurrentTransparent = isBlockTransparentForWorker(currentBlock);
    
    // 空气不参与面片剔除：透明方块对空气应该渲染面
    if (isNeighborAir) {
      return true;
    }
    
    // 只有相同的透明方块才进行内部剔除
    if (isCurrentTransparent && isNeighborTransparent && !isNeighborWater && !isNeighborLeaves) {
      // 检查是否为相同类型的透明方块
      if (currentBlock === neighborBlock) {
        // 相同透明方块：剔除（内部面隐藏）
        return false;
      }
      // 不同类型透明方块：渲染面
      return true;
    }
    // 火把和门是 InstancedMesh 渲染，不参与面片剔除
    // 如果相邻是火把或门，则渲染面
    if (isTorchBlock(neighborBlock) || isDoorBlock(neighborBlock)) {
      return true;
    }
    // 如果相邻是透明方块（包括水），则渲染面
    return isNeighborTransparent;
  }
}

// 判断方块是否使用镂空材质渲染（alphaTest）
// 使用数据驱动的透明属性
function isTransparentRender(blockType) {
  return isBlockTransparentForWorker(blockType);
}

// 判断方块是否使用水材质渲染（opacity 真透明）
// 使用数据驱动的液体属性
function isWaterRender(blockType) {
  return isBlockLiquidForWorker(blockType);
}

// 获取材质类型：'opaque' | 'transparent' | 'water'
function getMaterialType(blockType) {
  if (isWaterRender(blockType)) return 'water';
  if (isTransparentRender(blockType)) return 'transparent';
  return 'opaque';
}

