// 烧炼配方和燃料定义（从主线程动态接收）
// ============================================================
// 动态烧炼配方数据（由主线程通过 SET_SMELTING_DATA 消息设置）
let SMELTING_RECIPES = [];
// 动态燃料定义数据（由主线程通过 SET_SMELTING_DATA 消息设置）
let FUEL_DEFINITIONS = [];

/**
 * 设置烧炼数据（由主线程调用）
 * @param {Array} recipes - 烧炼配方数组
 * @param {Array} fuels - 燃料定义数组
 */
function setSmeltingData(recipes, fuels) {
  SMELTING_RECIPES = recipes || [];
  FUEL_DEFINITIONS = fuels || [];
}

function getSmeltingRecipe(inputItemId) {
  return SMELTING_RECIPES.find(recipe => recipe.input === inputItemId) || null;
}

function getFuelBurnTime(fuelItemId) {
  const fuel = FUEL_DEFINITIONS.find(f => f.itemId === fuelItemId);
  return fuel ? fuel.burnTime : 0;
}

// ============================================================
// GameWorker 主线程通信端口（MessageChannel）
// ============================================================
let mainPort = null; // 用于发送消息到主线程

// 发送消息到主线程（强制使用 MessageChannel）
function sendToMain(message, transferables) {
  if (!mainPort) {
    throw new Error('[GameWorker] mainPort not set! SET_MAIN_PORT must be called first.');
  }
  if (transferables && transferables.length > 0) {
    mainPort.postMessage(message, transferables);
  } else {
    mainPort.postMessage(message);
  }
}

