  if(!wet&&(!entity.logShore||logSwimSolid(this.getBlockAt(Math.floor(p.x),Math.floor(p.y-.05),Math.floor(p.z))))){
   entity.logShore=null;return behavior.call(this,entity,config,dt);
  }
